const startTime = Date.now();
const inputJson = $input.first()?.json || {};

// In LangChain toolCode, arguments may arrive in inputJson.action or parsed query
let action = inputJson.action || '';
let params = inputJson.params || {};

if (typeof inputJson.query === 'object' && inputJson.query !== null) {
  action = inputJson.query.action || action;
  params = inputJson.query.params || params;
} else if (typeof inputJson.query === 'string' && inputJson.query.trim().startsWith('{')) {
  try {
    const parsed = JSON.parse(inputJson.query);
    action = parsed.action || action;
    params = parsed.params || params;
  } catch (e) {}
}

action = String(action || '').trim().toLowerCase();

// 1. Resolve Trusted Session Context from Upstream Pipeline
const incoming = ($('PostgreSQL Persistent Conversation Store').first() || $('Message Normalizer').first() || $json)?.json || {};
const trustedBusinessCode = incoming.business_code || 'POS_RETAIL';
const instanceName = incoming.instance_name || 'action-instance';
const customerPhone = incoming.customerPhone || incoming.user_id || params.customer_phone || params.patient_phone || 'unknown';
const allowedTools = incoming.allowed_tools || ['action_gateway', 'query_business_data'];

// Anti-spoofing check
const spoofAttempt = !!(inputJson.business_code && inputJson.business_code !== trustedBusinessCode);
if (spoofAttempt) {
  return JSON.stringify({
    status: 'SECURITY_POLICY_DENIED',
    error_code: 'TENANT_SPOOFING_DETECTED',
    message: `[SECURITY ALERT] Tenant spoofing attempt blocked. Declared tenant does not match trusted session (${trustedBusinessCode}).`
  });
}

// 2. READ vs WRITE GUARD
const RECOGNIZED_READS = [
  'get_product', 'check_inventory', 'get_price', 'get_student_result',
  'get_doctor_schedule', 'get_doctors_by_specialty', 'get_departments',
  'search_knowledge_base', 'query_business_data', 'get_fees'
];

if (RECOGNIZED_READS.includes(action) || action.startsWith('get_') || action.startsWith('check_') || action.startsWith('search_')) {
  return JSON.stringify({
    status: 'READ_OPERATION_REJECTED',
    error_code: 'READ_OPERATION_NOT_PERMITTED_IN_ACTION_GATEWAY',
    action,
    message: `[ACTION GATEWAY NOTICE] '${action}' is a READ-ONLY operation. Action Gateway strictly executes state-changing WRITE and EXTERNAL operations. Direct read queries to Knowledge Gateway or Business Data Gateway.`
  });
}

// 3. Multi-Tenant Action Permissions
const ACTION_PERMS = {
  create_order: ['POS_RETAIL'],
  update_order: ['POS_RETAIL'],
  cancel_order: ['POS_RETAIL'],
  record_payment: ['POS_RETAIL'],
  sync_crm: ['POS_RETAIL'],
  submit_verification_request: ['BISE_EDU'],
  submit_service_application: ['BISE_EDU'],
  track_service_application: ['BISE_EDU'],
  create_appointment: ['HOSP_HEALTH'],
  book_appointment: ['HOSP_HEALTH'],
  reschedule_appointment: ['HOSP_HEALTH'],
  cancel_appointment: ['HOSP_HEALTH'],
  manage_calendar: ['HOSP_HEALTH'],
  send_notification: ['POS_RETAIL', 'BISE_EDU', 'HOSP_HEALTH'],
  call_external_api: ['POS_RETAIL', 'BISE_EDU', 'HOSP_HEALTH']
};

const authorizedTenants = ACTION_PERMS[action];
if (!authorizedTenants) {
  return JSON.stringify({
    status: 'ACTION_GATEWAY_DENIED',
    error_code: 'UNAPPROVED_ACTION_ROUTE',
    action,
    message: `[ACTION GATEWAY DENIAL] Action '${action}' is not an approved write action route. Write/external actions execute ONLY through approved routes.`
  });
}

if (!authorizedTenants.includes(trustedBusinessCode)) {
  return JSON.stringify({
    status: 'SECURITY_POLICY_DENIED',
    error_code: 'UNAUTHORIZED_TENANT_ACTION',
    action,
    tenant: trustedBusinessCode,
    authorized_tenants: authorizedTenants,
    message: `[ACTION GATEWAY DENIAL] Action '${action}' is strictly UNAUTHORIZED for tenant '${trustedBusinessCode}'. Execution blocked outside LLM.`
  });
}

// 4. Parameter Validation
function isValidPhone(p) { return p && typeof p === 'string' && /^\+?[0-9]{10,15}$/.test(p.replace(/[\s\-\(\)]/g, '')); }
function isValidDate(d) { return d && typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d); }
function isValidTime(t) { return t && typeof t === 'string' && /^([01]\d|2[0-3]):([0-5]\d)(:[0-5]\d)?$/.test(t); }

let valError = null;
if (action === 'create_order') {
  const phone = params.customer_phone || customerPhone;
  if (!phone || phone === 'unknown') valError = 'Valid customer_phone is required.';
} else if (action === 'update_order') {
  if (!params.order_number && !params.order_id) valError = 'order_number or order_id is required.';
} else if (action === 'cancel_order') {
  if (!params.order_number && !params.order_id) valError = 'order_number or order_id is required.';
} else if (action === 'record_payment') {
  if (!params.order_number && !params.order_id) valError = 'order_number or order_id is required.';
  else if (!params.amount_pkr || params.amount_pkr <= 0) valError = 'Positive amount_pkr is required.';
} else if (action === 'submit_verification_request') {
  if (!params.roll_number) valError = 'roll_number is required for verification request.';
} else if (action === 'submit_service_application') {
  if (!params.roll_number) valError = 'roll_number is required for service application.';
  else if (!params.application_type) valError = 'application_type is required.';
} else if (action === 'track_service_application') {
  if (!params.application_number && !params.request_ref && !params.roll_number) valError = 'application_number, request_ref or roll_number is required.';
} else if (action === 'book_appointment' || action === 'create_appointment') {
  const phone = params.patient_phone || customerPhone;
  if (!phone || phone === 'unknown') valError = 'Valid patient_phone is required.';
} else if (action === 'reschedule_appointment') {
  if (!params.appointment_number && !params.appointment_id) valError = 'appointment_number or appointment_id is required.';
} else if (action === 'cancel_appointment') {
  if (!params.appointment_number && !params.patient_phone && customerPhone === 'unknown') valError = 'appointment_number or patient_phone is required.';
}

if (valError) {
  return JSON.stringify({
    status: 'VALIDATION_FAILED',
    error_code: 'INVALID_ACTION_PARAMETERS',
    action,
    error: valError,
    message: `[ACTION GATEWAY PARAMETER ERROR] ${valError}`
  });
}

// 5. Execution Logic & State Resolution
let executionResult = null;

if (action === 'create_order') {
  const phone = (params.customer_phone || customerPhone).replace(/[\s\-\(\)]/g, '');
  const ordNum = params.order_number || `ORD-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;
  let total = params.total_amount_pkr || 0;
  if (Array.isArray(params.items) && params.items.length > 0) {
    total = params.items.reduce((acc, it) => acc + ((it.price_pkr || it.price || 1000) * (it.quantity || it.qty || 1)), 0);
  }
  executionResult = {
    order_number: ordNum,
    customer_phone: phone,
    total_amount_pkr: total,
    summary: `Order #${ordNum} created for ${phone}. Total: PKR ${total.toLocaleString('en-PK')}. Inventory deducted. Status: PENDING.`
  };
} else if (action === 'update_order') {
  const ordNum = params.order_number || params.order_id || 'ORD-2026-1001';
  const newStatus = (params.status || 'CONFIRMED').toUpperCase();
  executionResult = {
    order_number: ordNum,
    new_status: newStatus,
    summary: `Order #${ordNum} status updated to ${newStatus}.`
  };
} else if (action === 'cancel_order') {
  const ordNum = params.order_number || params.order_id || 'ORD-2026-1001';
  executionResult = {
    order_number: ordNum,
    summary: `Order #${ordNum} CANCELLED. All items restocked to inventory.`
  };
} else if (action === 'record_payment') {
  const ordNum = params.order_number || params.order_id || 'ORD-2026-1001';
  const trxRef = params.transaction_ref || `TRX-${Math.floor(100000 + Math.random() * 900000)}`;
  executionResult = {
    order_number: ordNum,
    transaction_ref: trxRef,
    amount_pkr: params.amount_pkr,
    summary: `Payment of PKR ${Number(params.amount_pkr).toLocaleString('en-PK')} recorded (Ref: ${trxRef}). Order #${ordNum} updated to PAID.`
  };
} else if (action === 'submit_verification_request') {
  const roll = String(params.roll_number).trim();
  const applicant = params.applicant_name || 'Applicant';
  const ref = `VER-2026-${Math.floor(1000 + Math.random() * 9000)}`;
  executionResult = {
    request_ref: ref,
    roll_number: roll,
    applicant_name: applicant,
    summary: `Verification request #${ref} submitted for Roll #${roll} (${applicant}). Fee Challan: PKR 1,500. Status: PENDING.`
  };
} else if (action === 'submit_service_application') {
  const roll = String(params.roll_number).trim();
  const appType = String(params.application_type || 'Certificate').trim();
  const fee = params.fee_pkr || 1500;
  const appNum = `APP-${appType.substring(0, 3).toUpperCase()}-2026-${Math.floor(1000 + Math.random() * 9000)}`;
  executionResult = {
    application_number: appNum,
    roll_number: roll,
    application_type: appType,
    fee_pkr: fee,
    summary: `BISE application #${appNum} submitted for ${appType} (Roll #${roll}). Fee: PKR ${fee}. Status: PROCESSING.`
  };
} else if (action === 'track_service_application') {
  const ref = String(params.application_number || params.request_ref || params.roll_number || 'APP-2026-1001').trim();
  executionResult = {
    reference: ref,
    status: 'PROCESSING',
    summary: `Official BISE Application/Verification #${ref} is currently active and marked as: PROCESSING at Central Verification Branch.`
  };
} else if (action === 'book_appointment' || action === 'create_appointment') {
  const phone = (params.patient_phone || customerPhone).replace(/[\s\-\(\)]/g, '');
  const docName = params.doctor_name || 'Consultant Specialist';
  const appDate = params.appointment_date || 'Upcoming Clinic Day';
  const appTime = params.appointment_time || '10:00 AM';
  const patientName = params.patient_name || 'Patient';
  const appNum = `APT-2026-${Math.floor(1000 + Math.random() * 9000)}`;
  executionResult = {
    appointment_number: appNum,
    doctor_name: docName,
    patient_name: patientName,
    appointment_date: appDate,
    appointment_time: appTime,
    summary: `Hospital OPD Appointment #${appNum} booked with ${docName} for ${patientName} on ${appDate} at ${appTime} PKT. Please arrive 15 minutes before slot time for vitals registration.`
  };
} else if (action === 'reschedule_appointment') {
  const appNum = params.appointment_number || params.appointment_id || 'APT-2026-1001';
  const newDate = params.new_appointment_date || 'New Date';
  const newTime = params.new_appointment_time || '11:00 AM';
  executionResult = {
    appointment_number: appNum,
    new_date: newDate,
    new_time: newTime,
    summary: `Appointment #${appNum} rescheduled to ${newDate} at ${newTime} PKT. Updated confirmation SMS sent.`
  };
} else if (action === 'cancel_appointment') {
  const appNum = params.appointment_number || 'APT-2026-1001';
  executionResult = {
    appointment_number: appNum,
    summary: `Appointment #${appNum} has been CANCELLED upon patient request. Slot released.`
  };
} else if (action === 'sync_crm') {
  const phone = (params.customer_phone || customerPhone).replace(/[\s\-\(\)]/g, '');
  executionResult = {
    customer_phone: phone,
    summary: `CRM lead ${phone} synchronized successfully.`
  };
} else {
  executionResult = {
    summary: `Action ${action} dispatched successfully through authorized gateway route.`
  };
}

// 6. Audit Logging (In-Memory Platform Audit Store)
globalThis.__platform_audit_logs = globalThis.__platform_audit_logs || [];
globalThis.__platform_audit_logs.push({
  business_code: trustedBusinessCode,
  instance_name: instanceName,
  customer_phone: customerPhone,
  action,
  params,
  processing_time_ms: Date.now() - startTime,
  timestamp: new Date().toISOString()
});

return `[Action Gateway Confirmation]: ${executionResult.summary}`;

// Phase 30: Result Validator & Response Guard
// Blocks false-success claims, enforces domain consistency, and guarantees verified responses.

const inputItem = $json;
const rawOutput = (inputItem.output || inputItem.text || '').trim();

// Heuristics for false success
const FALSE_SUCCESS_PATTERNS = [
  /order (?:has been |is )?(?:placed|created|confirmed|completed|processed|registered)/i,
  /appointment (?:has been |is )?(?:booked|scheduled|confirmed|rescheduled|registered)/i,
  /appointment (?:has been |is )?(?:cancelled|canceled)/i,
  /order (?:has been |is )?(?:cancelled|canceled)/i,
  /payment (?:has been |is )?(?:received|recorded|confirmed|successful|completed)/i,
  /(?:successfully|successful) (?:created|placed|booked|cancelled|canceled|rescheduled|updated|processed|recorded|submitted)/i,
  /(?:has been|have been) successfully/i,
  /i have (?:created|placed|booked|cancelled|canceled|rescheduled|updated|processed|recorded) your/i,
  /(?:order|booking|appointment) confirm ho gay[ai]/i,
  /(?:order|booking|appointment) cancel ho gay[ai]/i,
  /(?:kamyabi se|mubarak|tayyar hai|book ho chuk[ai])/i
];

// Check if tool executions in this turn encountered failure
let hasFailure = false;
let failureDetail = '';

// Check tool errors in input or execution context
if (inputItem.tool_error || inputItem.status === 'ERROR') {
  hasFailure = true;
  failureDetail = inputItem.message || inputItem.error || 'Downstream database validation failed.';
}

// Intercept false success if tool failed
if (hasFailure) {
  const claimsSuccess = FALSE_SUCCESS_PATTERNS.some(p => p.test(rawOutput));
  if (claimsSuccess) {
    const sanitized = `We apologize, but your requested operation could not be completed. Reason: ${failureDetail}. No changes were committed to your account. Please review your request and try again.`;
    return [{
      json: {
        ...inputItem,
        output: sanitized,
        validation_guard: {
          blocked: true,
          original_output: rawOutput,
          reason: 'FALSE_SUCCESS_BLOCKED'
        }
      }
    }];
  }
}

return [{
  json: {
    ...inputItem,
    output: rawOutput,
    validation_guard: {
      blocked: false,
      status: 'VERIFIED'
    }
  }
}];
